mapper.select:
SELECT A.*,
       ROW_NUMBER() OVER(ORDER BY A.created_at DESC) AS meetup_no,
      (SELECT COUNT(*) FROM meetup_applications WHERE meetup_id = a.meetup_id AND status = 'APPROVED') AS total_participants
  FROM meetups AS A
 WHERE A.status = #{status}
   AND A.title LIKE %#{title}%
   AND A.member_id = #{memberId};
 LIMIT #{start}, ${end};
